		{"cursor zero", "application/json", `{"cursor":0,"state":{}}`},
		{"cursor ahead", "application/json", `{"cursor":3,"state":{}}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			doc := "doc1"
