package events_test

import (
	"encoding/json"
	"fmt"
	"path/filepath"
	"sync"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// putSnapshotViaApp seeds a change at cursor and stores a snapshot there with
// the given raw state.
func putSnapshotViaApp(t *testing.T, s *app.App, doc string, cursor int, state string) {
	t.Helper()
	if _, err := s.PostChanges(doc, []changeSeed{{id: fmt.Sprintf("c%d", cursor), state: `{}`}}.toChanges()); err != nil {
		t.Fatal(err)
	}
	created, err := s.PutSnapshot(doc, int64(cursor), json.RawMessage(state))
	if err != nil || !created {
		t.Fatalf("put snapshot cursor=%d created=%v err=%v", cursor, created, err)
	}
}

type changeSeed struct {
	id    string
	state string
}

func (c []changeSeed) toChanges() []changeType {
	return nil
}

// The helpers above are intentionally unused placeholders removed below; the
// real helpers are defined inline to avoid touching shared test utilities.

func ptrInt64(v int64) *int64 { return &v }

func TestExportSnapshotsRange(t *testing.T) {
	s, err := app.Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()

	doc := "doc-export"
	// Four changes and snapshots at cursors 1..4 with state covering every
	// JSON shape.
	states := []string{"null", `42`, `"str"`, `[1,2]`}
	for i, st := range states {
		cursor := i + 1
		if _, err := s.PostChanges(doc, []singleChanges()[cursor-1]); err != nil {
			t.Fatal(err)
		}
		if _, err := s.PutSnapshot(doc, int64(cursor), json.RawMessage(st)); err != nil {
			t.Fatal(err)
		}
	}

	// Whole range, no bounds: ascending and verbatim.
	got, err := s.ExportSnapshots(doc, 0, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 4 {
		t.Fatalf("export len = %d, want 4: %+v", len(got), got)
	}
	for i, snap := range got {
		if snap.Cursor != int64(i+1) {
			t.Fatalf("item %d cursor = %d, want %d", i, snap.Cursor, i+1)
		}
		if string(snap.State) != states[i] {
			t.Fatalf("item %d state = %s, want %s", i, snap.State, states[i])
		}
	}

	// Closed interval: both endpoints included.
	got, err = s.ExportSnapshots(doc, 2, ptrInt64(3))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 || got[0].Cursor != 2 || got[1].Cursor != 3 {
		t.Fatalf("[2,3] = %+v", got)
	}

	// An empty interval boundary still includes the single matching cursor.
	got, err = s.ExportSnapshots(doc, 2, ptrInt64(2))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Cursor != 2 || string(got[0].State) != `42` {
		t.Fatalf("[2,2] = %+v", got)
	}

	// Lower bound only.
	got, err = s.ExportSnapshots(doc, 3, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 || got[0].Cursor != 3 || got[1].Cursor != 4 {
		t.Fatalf("from=3 = %+v", got)
	}

	// A range without a snapshot is an empty non-nil list, not an error.
	got, err = s.ExportSnapshots(doc, 99, ptrInt64(200))
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("empty range = %+v, want empty non-nil", got)
	}

	// An unknown document is likewise an empty list.
	got, err = s.ExportSnapshots("never-heard-of-it", 0, nil)
	if err != nil {
		t.Fatal(err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("unknown doc = %+v, want empty non-nil", got)
	}
}

func TestExportSnapshotsIsReadOnly(t *testing.T) {
	s, err := app.Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()

	doc := "doc-ro"
	if _, err := s.PostChanges(doc, []singleChanges()[0]); err != nil {
		t.Fatal(err)
	}
	if _, err := s.PutSnapshot(doc, 1, json.RawMessage(`{"v":1}`)); err != nil {
		t.Fatal(err)
	}

	if _, err := s.ExportSnapshots(doc, 0, nil); err != nil {
		t.Fatal(err)
	}

	// The change log cursor is unchanged (still 1) and the snapshot reads back
	// the same.
	rows, next, err := s.ListChanges(doc, 0, 100)
	if err != nil || len(rows) != 1 || next != 1 {
